def correct_bracketing(brackets: str) -> bool:
    count = 0
    for ch in brackets:
        if ch == '<':
            count += 1          # opening bracket
        elif ch == '>':
            count -= 1          # closing bracket
            if count < 0:      # more closings than openings so far → invalid
                return False

    return count == 0         # all opened brackets must be closed

